// node scripts/ens/abis.mjs
// Generates packages/ens/src/abi.generated.mjs from Sourcify (planning/SPEC/IDENTITY_ENS.md §2:
// ABIs are generated, never hand-written). Each contract is fetched at its address in the config
// file's `ens.contracts`; the generated file names the config key and the verified contract
// name, never an address (acceptance A7).

import { writeFileSync } from 'node:fs';
import { config, network } from '../../packages/config/index.mjs';

const OUT = new URL('../../packages/ens/src/abi.generated.mjs', import.meta.url);

// export name → config key. RootRegistry and ETHRegistry share PermissionedRegistry's ABI;
// the Universal Resolver proxy delegates every read to UniversalResolverV2.
const CONTRACTS = {
  permissionedRegistryAbi: 'ethRegistry',
  userRegistryAbi: 'userRegistryImpl',
  permissionedResolverAbi: 'permissionedResolverImpl',
  verifiableFactoryAbi: 'verifiableFactory',
  universalResolverAbi: 'universalResolverV2',
  universalResolverProxyAbi: 'universalResolverProxy',
  ethRegistrarAbi: 'ethRegistrar',
};

async function fetchAbi(key) {
  const address = config.ens.contracts[key];
  const chainId = network(config.ens.network).chainId;
  const url = `https://sourcify.dev/server/v2/contract/${chainId}/${address}?fields=abi,compilation`;
  for (let attempt = 1; ; attempt += 1) {
    try {
      const res = await fetch(url, { signal: AbortSignal.timeout(90_000) });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const body = await res.json();
      if (!Array.isArray(body.abi) || body.abi.length === 0) throw new Error('no ABI');
      return { abi: body.abi, name: body.compilation?.name, compiler: body.compilation?.compilerVersion };
    } catch (error) {
      if (attempt >= 3) throw new Error(`${key}: Sourcify fetch failed (${error.message})`);
    }
  }
}

const parts = [
  '// GENERATED by scripts/ens/abis.mjs from Sourcify (planning/SPEC/IDENTITY_ENS.md §2). Do not edit.',
  `// Fetched ${new Date().toISOString()}, chain ${network(config.ens.network).chainId}; addresses from the config file's ens.contracts.`,
  '',
];
for (const [exportName, key] of Object.entries(CONTRACTS)) {
  const { abi, name, compiler } = await fetchAbi(key);
  parts.push(`// ens.contracts.${key}: ${name} (solc ${compiler}), ${abi.length} entries`);
  parts.push(`export const ${exportName} = ${JSON.stringify(abi)};`, '');
  console.log(`${exportName}: ${name}, ${abi.length} entries`);
}
writeFileSync(OUT, parts.join('\n'));
console.log('wrote packages/ens/src/abi.generated.mjs');
